sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var r = ad.addGroupMemberAd('CN=Domain Admins,CN=Users,DC=example,DC=test', 'jdoe');
  if (r.ok) { stepResult.setFailed('add to a privileged group was accepted'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  var r = ad.removeGroupMemberAd('CN=Domain Admins,CN=Users,DC=example,DC=test', 'breakglass-01');
  if (r.ok) { stepResult.setFailed('remove from a privileged group was accepted (NEW-2 regressed)'); return; }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  // NOTE: classifyRequest({}) -- a request with NO group/role field at all --
  // is deliberately NOT this case. That shape means "not a privilege-grant
  // action" (a password reset, a disable, an attribute change) and correctly
  // classifies as confirmed-unprivileged; forcing it to inconclusive would
  // require an AC-6 expiry on requests that were never about privilege in the
  // first place (this exact regression broke atf-happy-path.xml when tried).
  // INCONCLUSIVE is for the other case: a target field WAS supplied but
  // classification couldn't resolve it -- e.g. a cloud groupId with no
  // privileged_role_template_ids/privileged_group_ids configured to check
  // against, which is exactly what this step now supplies.
  var pc = new x_fed_day2_ops.PrivilegeClassifier();
  var v = pc.classifyRequest({ groupId: 'unresolvable-cloud-group-id' });
  if (v.status !== 'inconclusive') {
    stepResult.setFailed('a supplied-but-unresolvable target returned ' + v.status + ', expected inconclusive');
    return;
  }
  var gate = new x_fed_day2_ops.EntraHelpdeskGate();
  var pre = gate.preflight({ requester_id: 'r', approver_id: 'a', groupId: 'unresolvable-cloud-group-id' });   // no expiry
  if (pre.ok) {
    stepResult.setFailed('inconclusive classification did not force the AC-6 expiry requirement');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
